; THE SINGING ENGINE 1: A MACHINE THAT SINGS (MEGA65)
; (C) 2026 Dawid Blachowski, with Claude (Anthropic's AI). A psinco. production.
; Generated by gen_engine.py. Plain NMOS 6502 opcodes; no zero page; self-modifying operands only
; in its own code. Bank 5 at $2000-$7FFF, bank 0 below; interrupts off while it runs.

MULA0 = $D770
MULA1 = $D771
MULA2 = $D772
MULA3 = $D773
MULB0 = $D774
MULB1 = $D775
MULO0 = $D778
MULO1 = $D779
MULO2 = $D77A
MULO3 = $D77B
MULO4 = $D77C
DMAMSB = $D701
DMABANK = $D702
DMAMB = $D704
DMAETRIG = $D705
AUDCTL = $D711
CH0RVOL = $D71C
CH0CTL = $D720
CH0BADR = $D721
CH0FREQ = $D724
CH0TADR = $D727
CH0VOL = $D729
CH0CUR = $D72A
TEXTYL = $D04E
TEXTYH = $D04F
RASTL = $D052
RASTH = $D053
FRAMES = $D7FA
KEYQ = $D610
SIDBASE = $D400

MB_FLAGS = $1E00
MB_VOL = $1E01
MB_LINESL = $1E02
MB_LINESH = $1E03
MB_METERK = $1E04
MB_SCRHI = $1E05
MB_EXIT = $1E10
MB_TPLAY = $1E11
MB_SLINES = $1E15
MB_UNDER = $1E19
MB_MINBUF = $1E1B
MB_TWRITE = $1E1D
MB_PEAK = $1E21

SEXT = $4000
GT0L = $4100
GT0H = $4200
GT1L = $4300
GT1H = $4400
GT2L = $4500
GT2H = $4600
KTL = $4700
KTH = $4800
FRL = $4900
FRH = $4A00
SIN8 = $4B00
NIL = $4C00
NIM = $4C80
NIH = $4D00
GTSEL = $4D80
SFPL = $4E00
SFPH = $4E80
SFNL = $4F00
SFNH = $4F80
VFIFO = $5000
EFIFO = $5100

ACCL = $5200
ACCH = $5210
INCL = $5220
INCH = $5230
TGT = $5240
P0 = $5250
P1 = $5251
P2 = $5252
PI0 = $5253
PI1 = $5254
PI2 = $5255
PTL = $5256
PTH = $5257
PLACE = $5258
VMODE = $5259
VCNT = $525A
VH = $525B
VPH = $525C
AHV = $5260
AFV = $5261
ANV = $5262
FRE = $5263
FRO = $5264
RL0 = $5270
RH0 = $527A
LL0 = $5284
LH0 = $528E
NLL = $5298
NLH = $5299
PH0 = $529A
PH1 = $529B
PH2 = $529C
INC0 = $529D
INC1 = $529E
INC2 = $529F
XL = $52A0
XH = $52A1
SRCL = $52A2
SRCH = $52A3
TL = $52A4
TH = $52A5
YL = $52A6
YH = $52A7
SCNT = $52A8
DS = $52A9
DL = $52AA
DM = $52AB
DH = $52AC
TWRITE = $52B0
TPLAY = $52B4
LASTIDX = $52B8
ETIME = $52BA
SLINES = $52C0
SLWIN = $52C4
METER = $52C6
METERA = $52C7
NEXTM = $52C9
UNDER = $52CD
MINBUF = $52CF
DONE = $52D1
EXITC = $52D2
RAS0 = $52D3
LASTF = $52D5
STALL = $52D6
VIDX = $52D7
EIDX = $52D8
VSRC = $52D9
ESRC = $52DC
TYB = $52E0
SAV711 = $52E2
SAVTYH = $52E3
NTSC = $52E4
LINES = $52E5
METERK = $52E7
VOL = $52E9
SCRHI = $52EA
SAVPAN = $52EB
RASL = $52EC
RASH = $52ED
PEAK = $52EE
T0 = $52F0
T1 = $52F1
T2 = $52F2
T3 = $52F3
D0 = $52F4
D1 = $52F5
CNTL = $52F6
CNTH = $52F7
DMALIST = $5300
RING = $6000

* = $2000
        JMP START
        .byte $53, $4E, $47, 1

; ======================================================================
; START: BASIC's call. Everything is set up, the ring is filled, then playback starts.
; ======================================================================
START:  SEI
        CLD
        ; clear the engine's state first: the saved registers and the mailbox copies live in it
        LDX #0
        TXA
ST_CLR: STA $5200,X
        INX
        BNE ST_CLR
        LDA #1
        STA XL
        LDA #255
        STA MINBUF
        STA MINBUF+1
        LDA AUDCTL
        STA SAV711
        LDA CH0RVOL
        STA SAVPAN
        LDA TEXTYL
        STA TYB
        LDA TEXTYH
        AND #$0F
        STA TYB+1
        LDA TEXTYH
        AND #$F0
        STA SAVTYH
        LDA MB_FLAGS
        AND #1
        STA NTSC
        LDA MB_VOL
        STA VOL
        LDA MB_LINESL
        STA LINES
        LDA MB_LINESH
        STA LINES+1
        LDA MB_METERK
        STA METERK
        LDA MB_SCRHI
        STA SCRHI
        ; the SID frequency table for this video mode
        LDA NTSC
        BEQ ST_PAL
        LDA #>SFNL
        STA EVF1+2
        LDA #>SFNH
        STA EVF2+2
        JMP ST_TAB
ST_PAL: LDA #>SFPL
        STA EVF1+2
        LDA #>SFPH
        STA EVF2+2
ST_TAB:
        ; audio DMA channel 0 stopped while the ring is filled
        LDA #0
        STA CH0CTL
        ; the ring buffer silent
        LDX #0
        TXA
ST_RCL: STA RING,X
        STA RING+$100,X
        STA RING+$200,X
        STA RING+$300,X
        STA RING+$400,X
        STA RING+$500,X
        STA RING+$600,X
        STA RING+$700,X
        STA RING+$800,X
        STA RING+$900,X
        STA RING+$A00,X
        STA RING+$B00,X
        STA RING+$C00,X
        STA RING+$D00,X
        STA RING+$E00,X
        STA RING+$F00,X
        INX
        BNE ST_RCL
        LDA #<RING
        STA WP1+1
        LDA #<(RING+1)
        STA WP2+1
        LDA #>RING
        STA WP1+2
        STA WP2+2
        ; the multiplier's B input stays below 65536
        LDA #0
        STA $D776
        STA $D777
        ; drop keys already waiting
ST_KEY: LDA KEYQ
        BEQ ST_KEY2
        STA KEYQ
        JMP ST_KEY
ST_KEY2:
        ; the two streams: 256 bytes each from attic RAM
        LDA #<0
        STA VSRC
        LDA #>0
        STA VSRC+1
        LDA #0
        STA VSRC+2
        LDA #<0
        STA ESRC
        LDA #>0
        STA ESRC+1
        LDA #1
        STA ESRC+2
        LDA #0
        JSR VFILL
        LDA #$80
        JSR VFILL
        LDA #0
        JSR EFILL
        LDA #$80
        JSR EFILL
        LDA #0
        STA VIDX
        STA EIDX
        ; the first event group's time
        JSR EGET
        STA ETIME
        JSR EGET
        STA ETIME+1
        ; fill the ring before playback starts
ST_PRE: JSR FRAME
        JSR BLOCK
        JSR ADDW
        LDA TWRITE+1
        CMP #>1948
        BCC ST_PRE
        BNE ST_GO
        LDA TWRITE
        CMP #<1948
        BCC ST_PRE
ST_GO:
        ; audio DMA channel 0: the ring, looping, 16-bit signed, centred
        LDA #$00
        STA CH0BADR
        LDA #>RING
        STA CH0BADR+1
        LDA #$05
        STA CH0BADR+2
        LDA #<4142
        STA CH0FREQ
        LDA #>4142
        STA CH0FREQ+1
        LDA #0
        STA CH0FREQ+2
        LDA #$00
        STA CH0TADR
        LDA #>(RING+$1000)
        STA CH0TADR+1
        LDA VOL
        STA CH0VOL
        STA CH0RVOL
        LDA #$00
        STA CH0CUR
        LDA #>RING
        STA CH0CUR+1
        LDA #$05
        STA CH0CUR+2
        LDA #0
        STA $D72D
        STA $D72E
        STA $D72F
        LDA SAV711
        AND #$08
        ORA #$80
        STA AUDCTL
        LDA #$C3
        STA CH0CTL
        LDA FRAMES
        STA LASTF

; ======================================================================
; MAIN: the play position, due events, keys, the meter, then a block if there is room
; ======================================================================
MAIN:   JSR PLAYPOS
        LDA EXITC
        BEQ MN_A
        JMP FINISH
MN_A:   JSR EVENTS
        LDA DONE
        BEQ MN_B
        JMP FINISH
MN_B:   JSR KEYS
        LDA EXITC
        BEQ MN_C
        JMP FINISH
MN_C:
        JSR METERUP
        ; waiting = TWRITE - TPLAY
        SEC
        LDA TWRITE
        SBC TPLAY
        STA T0
        LDA TWRITE+1
        SBC TPLAY+1
        STA T1
        LDA TWRITE+2
        SBC TPLAY+2
        LDA TWRITE+3
        SBC TPLAY+3
        BCS MN_OK
        ; the DMA overtook the writer: count it, and make the writer catch up
        INC UNDER
        BNE MN_UR
        INC UNDER+1
MN_UR:  JSR FRAME
        JSR BLOCK
        JSR ADDW
        JMP MAIN
MN_OK:  LDA T1
        CMP MINBUF+1
        BCC MN_MIN
        BNE MN_ROOM
        LDA T0
        CMP MINBUF
        BCS MN_ROOM
MN_MIN: LDA T0
        STA MINBUF
        LDA T1
        STA MINBUF+1
MN_ROOM:
        LDA T1
        CMP #>1982
        BCC MN_BLK
        BNE IDLE
        LDA T0
        CMP #<1982
        BCC MN_BLK
        BEQ MN_BLK
IDLE:   JMP MAIN
MN_BLK: JSR RASTER
        LDA RASL
        STA RAS0
        LDA RASH
        STA RAS0+1
        JSR FRAME
        JSR BLOCK
        JSR RASTER
        SEC
        LDA RASL
        SBC RAS0
        STA T0
        LDA RASH
        SBC RAS0+1
        STA T1
        BCS MN_R1
        CLC
        LDA T0
        ADC LINES
        STA T0
        LDA T1
        ADC LINES+1
        STA T1
MN_R1:  CLC
        LDA SLINES
        ADC T0
        STA SLINES
        LDA SLINES+1
        ADC T1
        STA SLINES+1
        LDA SLINES+2
        ADC #0
        STA SLINES+2
        LDA SLINES+3
        ADC #0
        STA SLINES+3
        CLC
        LDA SLWIN
        ADC T0
        STA SLWIN
        LDA SLWIN+1
        ADC T1
        STA SLWIN+1
        JSR ADDW
        JMP MAIN

; ======================================================================
; FINISH: silence, everything back as found, the results for BASIC
; ======================================================================
FINISH: LDA #0
        STA CH0CTL
        LDX #$7F
FN_SID: STA SIDBASE,X
        DEX
        BPL FN_SID
        LDA SAV711
        AND #$BF
        STA AUDCTL
        LDA SAVPAN
        STA CH0RVOL
        LDA TYB
        STA TEXTYL
        LDA TYB+1
        ORA SAVTYH
        STA TEXTYH
        LDA EXITC
        STA MB_EXIT
        LDX #3
FN_CP:  LDA TPLAY,X
        STA MB_TPLAY,X
        LDA SLINES,X
        STA MB_SLINES,X
        LDA TWRITE,X
        STA MB_TWRITE,X
        DEX
        BPL FN_CP
        LDA UNDER
        STA MB_UNDER
        LDA UNDER+1
        STA MB_UNDER+1
        LDA MINBUF
        STA MB_MINBUF
        LDA MINBUF+1
        STA MB_MINBUF+1
        LDA PEAK
        STA MB_PEAK
        CLI
        RTS

ADDW:   CLC
        LDA TWRITE
        ADC #50
        STA TWRITE
        BCC AW1
        INC TWRITE+1
        BNE AW1
        INC TWRITE+2
        BNE AW1
        INC TWRITE+3
AW1:    RTS

; the physical raster line, 0-1023, in RASL/RASH
RASTER: LDA RASTH
        AND #$07
        STA RASH
        LDA RASTL
        STA RASL
        LDA RASTH
        AND #$07
        CMP RASH
        BEQ RA1
        STA RASH
        LDA RASTL
        STA RASL
RA1:    RTS

; ======================================================================
; PLAYPOS: where the DMA reads, added to TPLAY; a DMA that stops moving ends the show ($FE)
; ======================================================================
PLAYPOS:
        LDA CH0CUR+1
        STA T1
        LDA CH0CUR
        STA T0
        LDA CH0CUR+1
        CMP T1
        BEQ PP1
        STA T1
        LDA CH0CUR
        STA T0
PP1:    LDA T1
        SEC
        SBC #>RING
        AND #$0F
        LSR A
        STA T1
        LDA T0
        ROR A
        STA T0
        SEC
        LDA T0
        SBC LASTIDX
        STA D0
        LDA T1
        SBC LASTIDX+1
        AND #$07
        STA D1
        LDA T0
        STA LASTIDX
        LDA T1
        STA LASTIDX+1
        LDA D0
        ORA D1
        BEQ PP_STILL
        CLC
        LDA TPLAY
        ADC D0
        STA TPLAY
        LDA TPLAY+1
        ADC D1
        STA TPLAY+1
        LDA TPLAY+2
        ADC #0
        STA TPLAY+2
        LDA TPLAY+3
        ADC #0
        STA TPLAY+3
        LDA #0
        STA STALL
        LDA FRAMES
        STA LASTF
        RTS
PP_STILL:
        LDA FRAMES
        CMP LASTF
        BEQ PP2
        STA LASTF
        INC STALL
        LDA STALL
        CMP #50
        BCC PP2
        LDA #$FE
        STA EXITC
PP2:    RTS

; ======================================================================
; KEYS: Q quits (exit code $51); other keys are dropped
; ======================================================================
KEYS:   LDA KEYQ
        BEQ KY0
        STA KEYQ
        CMP #$51
        BEQ KYQ
        CMP #$71
        BNE KY0
KYQ:    LDA #$51
        STA EXITC
KY0:    RTS

; ======================================================================
; METERUP: every 10,000 samples played, the voice's share of the last second, as two digits
; ======================================================================
METERUP:
        LDA METER
        BNE MU_GO
        RTS
MU_GO:  SEC
        LDA TPLAY
        SBC NEXTM
        LDA TPLAY+1
        SBC NEXTM+1
        LDA TPLAY+2
        SBC NEXTM+2
        LDA TPLAY+3
        SBC NEXTM+3
        BCS MU_T
        RTS
MU_T:
        LDA SLWIN
        STA MULA0
        LDA SLWIN+1
        STA MULA1
        LDA #0
        STA MULA2
        STA MULA3
        LDA METERK
        STA MULB0
        LDA #0
        STA MULB1
        LDA MULO3
        BNE MU99
        LDA MULO2
        CMP #100
        BCC MU1
MU99:   LDA #99
MU1:    CMP PEAK
        BCC MU2
        STA PEAK
MU2:    LDX #$30
MU3:    CMP #10
        BCC MU4
        SBC #10
        INX
        JMP MU3
MU4:    ORA #$30
        STA MUW2+1
        TXA
MUW1:   STA $0800
MUW2:   LDA #0
MUW3:   STA $0801
        LDA #0
        STA SLWIN
        STA SLWIN+1
        CLC
        LDA NEXTM
        ADC #<10000
        STA NEXTM
        LDA NEXTM+1
        ADC #>10000
        STA NEXTM+1
        LDA NEXTM+2
        ADC #0
        STA NEXTM+2
        LDA NEXTM+3
        ADC #0
        STA NEXTM+3
MU0:    RTS

; ======================================================================
; The streams: VGET and EGET return the next byte; at each half of the 256-byte FIFO the half
; just read is refilled from attic RAM by DMA (VFILL/EFILL: A = $00 or $80, the half).
; They keep the caller's carry, also when they refill: callers add across two calls.
; ======================================================================
VGET:   LDX VIDX
        LDA VFIFO,X
        INX
        STX VIDX
        PHA
        TXA
        AND #$7F
        BNE VG1
        PHP
        TXA
        EOR #$80
        JSR VFILL
        PLP
VG1:    PLA
        RTS

EGET:   LDX EIDX
        LDA EFIFO,X
        INX
        STX EIDX
        PHA
        TXA
        AND #$7F
        BNE EG1
        PHP
        TXA
        EOR #$80
        JSR EFILL
        PLP
EG1:    PLA
        RTS

VFILL:  STA DMALIST+12
        LDA #>VFIFO
        STA DMALIST+13
        LDA VSRC
        STA DMALIST+9
        LDA VSRC+1
        STA DMALIST+10
        LDA VSRC+2
        STA DMALIST+11
        JSR DODMA
        CLC
        LDA VSRC
        ADC #$80
        STA VSRC
        LDA VSRC+1
        ADC #0
        STA VSRC+1
        LDA VSRC+2
        ADC #0
        AND #$0F
        STA VSRC+2
        RTS

EFILL:  STA DMALIST+12
        LDA #>EFIFO
        STA DMALIST+13
        LDA ESRC
        STA DMALIST+9
        LDA ESRC+1
        STA DMALIST+10
        LDA ESRC+2
        STA DMALIST+11
        JSR DODMA
        CLC
        LDA ESRC
        ADC #$80
        STA ESRC
        LDA ESRC+1
        ADC #0
        STA ESRC+1
        LDA ESRC+2
        ADC #0
        AND #$0F
        STA ESRC+2
        RTS

; an enhanced DMA job: copy 128 bytes from attic RAM ($80 megabyte) to bank 5
DODMA:  LDA #$0B
        STA DMALIST
        LDA #$80
        STA DMALIST+1
        STA DMALIST+2
        LDA #$81
        STA DMALIST+3
        LDA #$00
        STA DMALIST+4
        STA DMALIST+5
        STA DMALIST+6
        LDA #$80
        STA DMALIST+7
        LDA #0
        STA DMALIST+8
        LDA #$05
        STA DMALIST+14
        LDA #0
        STA DMALIST+15
        STA DMALIST+16
        STA DMALIST+17
        LDA #$05
        STA DMABANK
        LDA #>DMALIST
        STA DMAMSB
        LDA #0
        STA DMAMB
        LDA #<DMALIST
        STA DMAETRIG
        RTS

; ======================================================================
; EVENTS: every group whose time has come (ETIME <= TPLAY)
; ======================================================================
EVENTS: LDA DONE
        BNE EVX
        SEC
        LDA TPLAY
        SBC ETIME
        LDA TPLAY+1
        SBC ETIME+1
        LDA TPLAY+2
        SBC ETIME+2
        LDA TPLAY+3
        SBC ETIME+3
        BCC EVX
EVCMD:  JSR EGET
        BEQ EVNEXT
        CMP #$01
        BEQ EVPOKE
        CMP #$02
        BEQ EVSID
        CMP #$03
        BEQ EVSIDF
        CMP #$04
        BNE EVC5
        JMP EVTXT
EVC5:
        CMP #$05
        BNE EVC6
        JMP EVTYP
EVC6:   CMP #$06
        BNE EVC7
        JMP EVFILL
EVC7:   CMP #$07
        BNE EVC8
        JMP EVMON
EVC8:   CMP #$08
        BNE EVC9
        LDA #0
        STA METER
        JMP EVCMD
EVC9:   LDA #1
        STA DONE
EVX:    RTS
EVNEXT: JSR EGET
        CLC
        ADC ETIME
        STA ETIME
        JSR EGET
        ADC ETIME+1
        STA ETIME+1
        LDA ETIME+2
        ADC #0
        STA ETIME+2
        LDA ETIME+3
        ADC #0
        STA ETIME+3
        JMP EVENTS
EVPOKE: JSR EGET
        STA EVP1+1
        JSR EGET
        STA EVP1+2
        JSR EGET
EVP1:   STA $0400
        JMP EVCMD
EVSID:  JSR EGET
        STA T0
        JSR EGET
        LDX T0
        STA SIDBASE,X
        JMP EVCMD
EVSIDF: JSR EGET
        STA T0
        JSR EGET
        TAX
        LDY T0
EVF1:   LDA SFPL,X
        STA SIDBASE,Y
EVF2:   LDA SFPH,X
        STA SIDBASE+1,Y
        JMP EVCMD
EVTXT:  JSR EGET
        STA T0
        JSR EGET
        CLC
        ADC SCRHI
        STA EVT1+2
        LDA T0
        STA EVT1+1
        JSR EGET
        STA T1
        LDA #0
        STA T2
EVT0:   LDA T2
        CMP T1
        BCS EVT2
        JSR EGET
        LDX T2
EVT1:   STA $0800,X
        INC T2
        JMP EVT0
EVT2:   JMP EVCMD
EVTYP:  JSR EGET
        CLC
        ADC TYB
        STA TEXTYL
        JSR EGET
        ADC TYB+1
        AND #$0F
        ORA SAVTYH
        STA TEXTYH
        JMP EVCMD
EVFILL: JSR EGET
        STA EVL1+1
        JSR EGET
        CLC
        ADC SCRHI
        STA EVL1+2
        JSR EGET
        STA CNTL
        JSR EGET
        STA CNTH
        JSR EGET
        STA T3
EVL0:   LDA CNTL
        ORA CNTH
        BEQ EVL2
        LDA T3
EVL1:   STA $0800
        INC EVL1+1
        BNE EVL3
        INC EVL1+2
EVL3:   LDA CNTL
        BNE EVL4
        DEC CNTH
EVL4:   DEC CNTL
        JMP EVL0
EVL2:   JMP EVCMD
EVMON:  JSR EGET
        STA MUW1+1
        STA MUW3+1
        INC MUW3+1
        JSR EGET
        CLC
        ADC SCRHI
        STA MUW1+2
        STA MUW3+2
        LDA MUW1+1
        CMP #$FF
        BNE EVM1
        INC MUW3+2
EVM1:   LDA #1
        STA METER
        LDA #0
        STA SLWIN
        STA SLWIN+1
        CLC
        LDA TPLAY
        ADC #<10000
        STA NEXTM
        LDA TPLAY+1
        ADC #>10000
        STA NEXTM+1
        LDA TPLAY+2
        ADC #0
        STA NEXTM+2
        LDA TPLAY+3
        ADC #0
        STA NEXTM+3
        JMP EVCMD

; ======================================================================
; FRAME: the voice stream's next frame, then the values the samples use
; ======================================================================
FRAME:  LDA VMODE
        CMP #2
        BNE FR0
        JMP DERIVE
FR0:    LDA VCNT
        BEQ FR0R
        JMP FRAPPLY
FR0R:
        JSR VGET
        CMP #$FF
        BNE FR1
        LDA #2
        STA VMODE
        JMP DERIVE
FR1:    CMP #$80
        BCC FRRAMP
        AND #$7F
        CLC
        ADC #1
        STA VCNT
        LDA #0
        STA VMODE
        JMP FRAPPLY
FRRAMP: STA VH
        LDX #0
FRT:    STX T3
        JSR VGET
        LDX T3
        STA TGT,X
        INX
        CPX #15
        BNE FRT
        JSR VGET
        STA PTL
        JSR VGET
        STA PTH
        JSR VGET
        STA PLACE
        ; increments: ((target << 8) - acc) >> H, H = 0 needs none
        LDA VH
        BNE FRI
        JMP FRCNT
FRI:    LDX #0
FRI1:   SEC
        LDA #0
        SBC ACCL,X
        STA DL
        LDA TGT,X
        SBC ACCH,X
        STA DH
        LDA #0
        SBC #0
        STA DS
        LDY VH
FRI2:   LDA DS
        CMP #$80
        ROR DS
        ROR DH
        ROR DL
        DEY
        BNE FRI2
        LDA DL
        STA INCL,X
        LDA DH
        STA INCH,X
        INX
        CPX #15
        BNE FRI1
        SEC
        LDA #0
        SBC P0
        STA DL
        LDA PTL
        SBC P1
        STA DM
        LDA PTH
        SBC P2
        STA DH
        LDA #0
        SBC #0
        STA DS
        LDY VH
FRI3:   LDA DS
        CMP #$80
        ROR DS
        ROR DH
        ROR DM
        ROR DL
        DEY
        BNE FRI3
        LDA DL
        STA PI0
        LDA DM
        STA PI1
        LDA DH
        STA PI2
FRCNT:  LDA #1
        LDY VH
        BEQ FRC2
FRC1:   ASL A
        DEY
        BNE FRC1
FRC2:   STA VCNT
        LDA #1
        STA VMODE
FRAPPLY:
        DEC VCNT
        LDA VMODE
        BEQ DERIVE
        LDA VCNT
        BNE FRADD
        ; the ramp's last frame: exactly on the targets
        LDX #14
FRS:    LDA TGT,X
        STA ACCH,X
        LDA #0
        STA ACCL,X
        DEX
        BPL FRS
        LDA #0
        STA P0
        LDA PTL
        STA P1
        LDA PTH
        STA P2
        JMP DERIVE
FRADD:  LDX #14
FRA1:   CLC
        LDA ACCL,X
        ADC INCL,X
        STA ACCL,X
        LDA ACCH,X
        ADC INCH,X
        STA ACCH,X
        DEX
        BPL FRA1
        CLC
        LDA P0
        ADC PI0
        STA P0
        LDA P1
        ADC PI1
        STA P1
        LDA P2
        ADC PI2
        STA P2

; DERIVE: reflection coefficients, the source levels, the noise place, the pitch with vibrato
DERIVE:
