DJD9:
        LDA ACCH+10
        STA AVK+1
        ; aspiration: AH * 32 for the multiplier ((noise * AH) >> 11 = bytes 2-3)
        LDA ACCH+11
        STA AHV
        STA T0
        LDA #0
        LSR T0
        ROR A
        LSR T0
        ROR A
        LSR T0
        ROR A
        STA ASPK+1
        LDA T0
        STA ASPKH+1
        ; frication, at an even or an odd place
        LDA #0
        STA FRE
        STA FRO
        LDA ACCH+12
        BEQ DFR0
        STA T0
        LDA #0
        LSR T0
        ROR A
        LSR T0
        ROR A
        LSR T0
        ROR A
        STA FREK+1
        STA FROK+1
        LDA T0
        STA FREKH+1
        STA FROKH+1
        LDA PLACE
        CLC
        ADC #<RL0
        STA FREA1+1
        STA FREA2+1
        STA FROA1+1
        STA FROA2+1
        LDA #>RL0
        ADC #0
        STA FREA1+2
        STA FREA2+2
        STA FROA1+2
        STA FROA2+2
        LDA PLACE
        CLC
        ADC #<RH0
        STA FREA3+1
        STA FREA4+1
        STA FROA3+1
        STA FROA4+1
        LDA #>RH0
        ADC #0
        STA FREA3+2
        STA FREA4+2
        STA FROA3+2
        STA FROA4+2
        LDA PLACE
        AND #1
        BNE DFRO
        LDA #1
        STA FRE
        JMP DFR0
DFRO:   LDA #1
        STA FRO
DFR0:   LDA ACCH+13
        STA ANV
        STA NASK+1
        ; vibrato: (SIN8[VPH] * VD) >> 8
        LDX VPH
        LDA SIN8,X
        STA MULA0
        TAY
        LDA SEXT,Y
        STA MULA1
        STA MULA2
        STA MULA3
        LDA ACCH+14
        STA MULB0
        LDA #0
        STA MULB1
        CLC
        LDA P1
        ADC MULO1
        STA T0
        LDA P2
        ADC MULO2
        STA T1
        ; T1 = the note, T0 = 1/256 of a semitone; the pulse for this note
        LDX T1
        LDA GTSEL,X
        TAY
        LDA GTHI,Y
        STA GTLOP+2
        CLC
        ADC #1
        STA GTHOP+2
        ; INC = NI[n] + (NI[n] * FR[f]) >> 16
        LDA NIL,X
        STA MULA0
        STA T2
        LDA NIM,X
        STA MULA1
        STA T3
        LDA NIH,X
        STA MULA2
        STA D0
        LDA #0
        STA MULA3
        LDX T0
        LDA FRL,X
        STA MULB0
        LDA FRH,X
        STA MULB1
        CLC
        LDA T2
        ADC MULO2
        STA INC0
        LDA T3
        ADC MULO3
        STA INC1
        LDA D0
        ADC MULO4
        STA INC2
        CLC
        LDA VPH
        ADC #7
        STA VPH
        RTS

GTHI:   .byte >GT0L, >GT1L, >GT2L

; ======================================================================
; BLOCK: one frame of samples into the ring
; ======================================================================
BLOCK:  LDA #50
        STA SCNT
SAMPLE: CLC
        LDA PH0
        ADC INC0
        STA PH0
        LDA PH1
        ADC INC1
        STA PH1
        LDA PH2
        ADC INC2
        STA PH2
        TAX
GTLOP:  LDA GT0L,X
        STA MULA0
GTHOP:  LDA GT0H,X
        STA MULA1
        TAY
        LDA SEXT,Y
        STA MULA2
        STA MULA3
AVK:    LDA #0
        STA MULB0
        LDA #0
        STA MULB1
        LDA MULO1
        STA SRCL
        LDA MULO2
        STA SRCH
        ; noise: xorshift 7, 9, 8
        LDA XH
        LSR A
        LDA XL
        ROR A
        EOR XH
        STA XH
        LDA #0
        ROR A
        EOR XL
        STA XL
        LDA XH
        LSR A
        EOR XL
        STA XL
        EOR XH
        STA XH
        ; aspiration at the glottis
        LDA AHV
        BEQ NOASP
        LDA XL
        STA MULA0
        LDA XH
        STA MULA1
        TAY
        LDA SEXT,Y
        STA MULA2
        STA MULA3
ASPK:   LDA #0
        STA MULB0
ASPKH:  LDA #0
        STA MULB1
        CLC
        LDA SRCL
        ADC MULO2
        STA SRCL
        LDA SRCH
        ADC MULO3
        STA SRCH
NOASP:
        ; the glottis: R0 = L0 - (L0 >> 2) + source
        LDA LH0
        STA TH
        LDA LL0
        STA TL
        LDA TH
        CMP #$80
        ROR A
        STA TH
        LDA TL
        ROR A
        STA TL
        LDA TH
        CMP #$80
        ROR A
        STA TH
        LDA TL
        ROR A
        STA TL
        SEC
        LDA LL0
        SBC TL
        STA TL
        LDA LH0
        SBC TH
        STA TH
        CLC
        LDA TL
        ADC SRCL
        STA RL0
        LDA TH
        ADC SRCH
        STA RH0
J2:    CLC
        LDA RL0+1
        ADC LL0+2
        STA MULA0
        LDA RH0+1
        ADC LH0+2
        STA MULA1
        TAY
